mapper.select:
SELECT  FROM file_analysis_task t LEFT JOIN sys_user u ON u.user_id=t.user_id

  AND t.user_id=#{userId}
  AND t.status=#{status}
  AND t.file_name LIKE CONCAT('%',#{fileName},'%')
  AND u.user_name LIKE CONCAT('%',#{userName},'%')
 ORDER BY t.id DESC

mapper.update:
UPDATE file_analysis_task SET status=#{status},processing_mode=#{processingMode},analysis_text=#{analysisText},model_name=#{modelName},
  error_code=#{errorCode},error_message=#{errorMessage},completed_at=#{completedAt},version=version+1,update_time=NOW()
WHERE id=#{id} AND status='PROCESSING' AND processing_mode='AUTO' AND version=#{version}

UPDATE file_analysis_task SET analysis_text=#{analysisText},status='SUCCEEDED',processing_mode='MANUAL',
  error_code=NULL,error_message=NULL,completed_at=#{completedAt},version=version+1,update_time=NOW(),update_by=#{updateBy}
WHERE id=#{id} AND version=#{version}
